def telemetry(package):
    return {'package_id':package.package_id,'view_count':len(package.views),'compatibility':package.compatibility.status.value,'complete_views':sum(v.status.value=='complete' for v in package.views),'degraded_views':sum(v.status.value=='degraded' for v in package.views),'unknown_views':sum(v.status.value=='unknown' for v in package.views),'missing_feature_count':sum(sum(f.missing for f in v.features) for v in package.views),'stale_feature_count':sum(sum(f.stale for f in v.features) for v in package.views),'mean_quality':round(sum(package.quality_vector)/max(1,len(package.quality_vector)),12)}
